using System.Globalization;
using System.Text;
using Elarion.Generators;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Text;

namespace Elarion.Spreadsheets.Generators;

public sealed partial class SpreadsheetRecordGenerator {
    private const string Header =
        "// <auto-generated/>\n#nullable enable\n#pragma warning disable CS1591 // Generated code is not documented; a consuming project that enables GenerateDocumentationFile must not be warned about it.\n";

    private static void EmitMapper(SourceProductionContext context, SpreadsheetRecordModel model) {
        var builder = new StringBuilder();
        builder.Append(Header).AppendLine();
        AppendNamespace(builder, model);

        var type = model.TypeFqn;
        builder.AppendLine($$"""
                             /// <summary>Generated spreadsheet row mapper for <see cref="{{type}}"/> (worksheet "{{EscapeXml(model.WorksheetName)}}").</summary>
                             {{model.Accessibility}} sealed class {{model.MapperName}} : global::Elarion.Spreadsheets.ISpreadsheetRowMapper<{{type}}> {
                                 /// <summary>The worksheet name the record declares, or its type name.</summary>
                                 public const string DefaultWorksheetName = {{SourceLiterals.String(model.WorksheetName)}};

                                 /// <summary>The shared stateless instance.</summary>
                                 public static {{model.MapperName}} Instance { get; } = new {{model.MapperName}}();

                                 private {{model.MapperName}}() {
                                 }

                                 /// <summary>The column table, in column order.</summary>
                                 internal static readonly global::Elarion.Spreadsheets.SpreadsheetColumn<{{type}}>[] ColumnTable = new global::Elarion.Spreadsheets.SpreadsheetColumn<{{type}}>[] {
                             """);

        for (var i = 0; i < model.Columns.Count; i++) {
            var column = model.Columns[i];
            builder.Append("        global::Elarion.Spreadsheets.Generated.SpreadsheetColumns.Create<").Append(type).Append(">(")
                .Append(i.ToString(CultureInfo.InvariantCulture)).Append(", ")
                .Append(SourceLiterals.String(column.Header)).Append(", ")
                .Append(SourceLiterals.String(column.PropertyName)).Append(", ")
                .Append("global::Elarion.Spreadsheets.SpreadsheetValueKind.").Append(column.Kind).Append(", ")
                .Append(column.IsNullable ? "true" : "false").Append(", ")
                .Append(SourceLiterals.String(column.Format)).Append(", ")
                .Append(DoubleLiteral(column.Width)).Append(", ")
                .Append(StringArray(column.Aliases)).Append(", ")
                .Append(StringArray(column.Choices))
                .Append(IsReadable(model, column) ? "" : ", isReadable: false").AppendLine("),");
        }

        builder.AppendLine($$"""
                                 };

                                 string global::Elarion.Spreadsheets.ISpreadsheetRowMapper<{{type}}>.WorksheetName => DefaultWorksheetName;

                                 global::System.Collections.Generic.IReadOnlyList<global::Elarion.Spreadsheets.SpreadsheetColumn<{{type}}>> global::Elarion.Spreadsheets.ISpreadsheetRowMapper<{{type}}>.Columns => ColumnTable;

                                 /// <inheritdoc />
                                 public void WriteRow({{type}} record, global::Elarion.Spreadsheets.Generated.SpreadsheetCellWriter writer) {
                             """);

        foreach (var column in model.Columns)
            builder.Append("        ").Append(WriteStatement(column)).AppendLine();

        builder.AppendLine("    }");
        builder.AppendLine();
        builder.AppendLine("    /// <inheritdoc />");
        builder.AppendLine($"    public bool HasValidation => {(model.HasValidation ? "true" : "false")};");
        builder.AppendLine();
        AppendReadRow(builder, model);

        foreach (var column in model.Columns) {
            if (column.WriteKind != WriteKind.Enum) continue;

            builder.AppendLine();
            builder.AppendLine($"    private static string LabelOf{column.PropertyName}({column.EnumTypeFqn} value) {{");
            builder.AppendLine("        return value switch {");
            foreach (var member in column.EnumMembers)
                builder.AppendLine(
                    $"            {column.EnumTypeFqn}.{Identifier(member.Name)} => {SourceLiterals.String(member.Label)},");

            // A value outside the declared members (a flags combination, a cast number) keeps its own text.
            builder.AppendLine("            _ => value.ToString()");
            builder.AppendLine("        };");
            builder.AppendLine("    }");

            if (!IsReadable(model, column)) continue;

            // Reading takes a member's label or its name, ignoring case and surrounding white space (FR-009).
            builder.AppendLine();
            builder.AppendLine($"    private static {column.EnumTypeFqn}? Parse{column.PropertyName}(string text) {{");
            foreach (var (text, member) in column.EnumMembers.Select(static member => (member.Label, member.Name))
                         .Concat(column.EnumMembers.Select(static member => (member.Name, member.Name)))
                         .GroupBy(static pair => pair.Item1, StringComparer.OrdinalIgnoreCase)
                         .Select(static group => group.First()))
                builder.AppendLine(
                    $"        if (string.Equals(text, {SourceLiterals.String(text)}, global::System.StringComparison.OrdinalIgnoreCase)) return {column.EnumTypeFqn}.{Identifier(member)};");

            builder.AppendLine("        return null;");
            builder.AppendLine("    }");
        }

        builder.AppendLine("}");
        context.AddSource($"{model.HintName}.SpreadsheetRowMapper.g.cs", SourceText.From(builder.ToString(), Encoding.UTF8));
    }

    /// <summary>Whether reading sets the column's property: settable, or passed to the constructor (FR-042).</summary>
    private static bool IsReadable(SpreadsheetRecordModel model, ColumnModel column) {
        return column.CanSet || model.ConstructorArguments.Contains(column.PropertyName);
    }

    /// <summary>
    /// Emits <c>ReadRow</c>: one typed read per readable column into a local, then, when the row has no error, the
    /// record built through its constructor and an object initializer. A non-nullable property is only reached with a
    /// value, because an empty cell or a missing column is an error first.
    /// </summary>
    private static void AppendReadRow(StringBuilder builder, SpreadsheetRecordModel model) {
        var type = model.TypeFqn;
        builder.AppendLine("    /// <inheritdoc />");
        builder.AppendLine($"    public {type}? ReadRow(global::Elarion.Spreadsheets.Generated.SpreadsheetCellReader reader) {{");
        if (model.ConstructionProblem is { } problem) {
            builder.AppendLine(
                $"        throw new global::System.NotSupportedException({SourceLiterals.String($"The spreadsheet record '{type.Replace("global::", "")}' cannot be read: {problem}.")});");
            builder.AppendLine("    }");
            return;
        }

        var readable = new List<(int Index, ColumnModel Column)>();
        for (var i = 0; i < model.Columns.Count; i++)
            if (IsReadable(model, model.Columns[i]))
                readable.Add((i, model.Columns[i]));

        foreach (var (index, column) in readable)
            builder.Append(ReadStatement(index, column));

        builder.AppendLine("        if (reader.HasErrors) return null;");
        builder.AppendLine();

        var arguments = model.ConstructorArguments.Select(name => Value(model.Columns.First(column => column.PropertyName == name)));
        var initialized = readable
            .Select(static pair => pair.Column)
            .Where(column => !model.ConstructorArguments.Contains(column.PropertyName))
            .ToList();
        builder.Append("        return new ").Append(type).Append('(').Append(string.Join(", ", arguments)).Append(')');
        if (initialized.Count == 0) {
            builder.AppendLine(";");
        }
        else {
            builder.AppendLine(" {");
            foreach (var column in initialized)
                builder.Append("            ").Append(Identifier(column.PropertyName)).Append(" = ").Append(Value(column)).AppendLine(",");

            builder.AppendLine("        };");
        }

        builder.AppendLine("    }");
    }

    /// <summary>The local of a column, as its property's type: non-nullable ones were checked present.</summary>
    private static string Value(ColumnModel column) {
        var local = Local(column);
        if (column.IsNullable) return local;

        return column.WriteKind == WriteKind.Text ? local + "!" : local + ".GetValueOrDefault()";
    }

    private static string ReadStatement(int index, ColumnModel column) {
        var i = index.ToString(CultureInfo.InvariantCulture);
        var local = Local(column);
        var valueType = column.ValueTypeFqn;
        switch (column.WriteKind) {
            case WriteKind.Enum:
                return $$"""
                                 {{valueType}}? {{local}} = null;
                                 if (reader.ReadChoice({{i}}) is { } {{local}}Text) {
                                     {{local}} = Parse{{column.PropertyName}}({{local}}Text);
                                     if ({{local}} is null) reader.RejectChoice({{i}});
                                 }

                         """;
            case WriteKind.Integer:
                return $"        var {local} = ({valueType}?)reader.ReadInteger({i}, {valueType}.MinValue, {valueType}.MaxValue);\n";
        }

        var call = column.WriteKind switch {
            WriteKind.Text => "ReadText",
            WriteKind.Boolean or WriteKind.LabelledBoolean => "ReadBoolean",
            WriteKind.UnsignedInteger => "ReadUnsignedInteger",
            WriteKind.Single => "ReadSingle",
            WriteKind.Double => "ReadDouble",
            WriteKind.Decimal => "ReadDecimal",
            WriteKind.DateTime => "ReadDateTime",
            WriteKind.Date => "ReadDate",
            WriteKind.Time => "ReadTime",
            WriteKind.DateTimeOffset => "ReadDateTimeOffset",
            WriteKind.Guid => "ReadGuid",
            _ => throw new InvalidOperationException("Unknown read kind " + column.WriteKind)
        };
        return $"        var {local} = reader.{call}({i});\n";
    }

    private static void EmitSelfMapping(SourceProductionContext context, SpreadsheetRecordModel model) {
        var builder = new StringBuilder();
        builder.Append(Header).AppendLine();
        AppendNamespace(builder, model);

        var mapperRef = model.Namespace.Length == 0
            ? "global::" + model.MapperName
            : "global::" + model.Namespace + "." + model.MapperName;
        var type = model.TypeFqn;

        builder.AppendLine($$"""
                             partial {{model.TypeKeyword}} {{model.TypeName}} : global::Elarion.Spreadsheets.ISpreadsheetRecord<{{type}}> {
                                 /// <summary>The record's generated spreadsheet mapper (a cached singleton).</summary>
                                 public static global::Elarion.Spreadsheets.ISpreadsheetRowMapper<{{type}}> SpreadsheetMapper => {{mapperRef}}.Instance;

                                 /// <summary>The record's spreadsheet columns, one per mapped property.</summary>
                                 public static class Columns {
                             """);

        for (var i = 0; i < model.Columns.Count; i++) {
            var column = model.Columns[i];
            builder.AppendLine($"        /// <summary>The column \"{EscapeXml(column.Header)}\".</summary>");
            builder.AppendLine(
                $"        public static readonly global::Elarion.Spreadsheets.SpreadsheetColumn<{type}> {Identifier(column.PropertyName)} = {mapperRef}.ColumnTable[{i.ToString(CultureInfo.InvariantCulture)}];");
        }

        builder.AppendLine("    }");
        builder.AppendLine("}");
        context.AddSource($"{model.HintName}.SpreadsheetRecord.g.cs", SourceText.From(builder.ToString(), Encoding.UTF8));
    }

    private static string WriteStatement(ColumnModel column) {
        var value = "record." + Identifier(column.PropertyName);
        return column.WriteKind switch {
            WriteKind.Text => $"writer.WriteText({value});",
            WriteKind.Boolean => $"writer.WriteBoolean({value});",
            WriteKind.Integer => $"writer.WriteInteger({value});",
            WriteKind.UnsignedInteger => $"writer.WriteUnsignedInteger({value});",
            WriteKind.Single => $"writer.WriteSingle({value});",
            WriteKind.Double => $"writer.WriteDouble({value});",
            WriteKind.Decimal => $"writer.WriteDecimal({value});",
            WriteKind.DateTime => $"writer.WriteDateTime({value});",
            WriteKind.Date => $"writer.WriteDate({value});",
            WriteKind.Time => $"writer.WriteTime({value});",
            WriteKind.DateTimeOffset => $"writer.WriteDateTimeOffset({value});",
            WriteKind.Guid => $"writer.WriteGuid({value});",
            WriteKind.LabelledBoolean => column.IsNullable
                ? $"writer.WriteText({value} is {{ }} {Local(column)} ? ({Local(column)} ? {SourceLiterals.String(column.TrueLabel)} : {SourceLiterals.String(column.FalseLabel)}) : null);"
                : $"writer.WriteText({value} ? {SourceLiterals.String(column.TrueLabel)} : {SourceLiterals.String(column.FalseLabel)});",
            WriteKind.Enum => column.IsNullable
                ? $"writer.WriteText({value} is {{ }} {Local(column)} ? LabelOf{column.PropertyName}({Local(column)}) : null);"
                : $"writer.WriteText(LabelOf{column.PropertyName}({value}));",
            _ => throw new InvalidOperationException("Unknown write kind " + column.WriteKind)
        };
    }

    private static string Local(ColumnModel column) {
        return "__" + column.PropertyName;
    }

    private static void AppendNamespace(StringBuilder builder, SpreadsheetRecordModel model) {
        if (model.Namespace.Length == 0) return;

        builder.Append("namespace ").Append(model.Namespace).AppendLine(";");
        builder.AppendLine();
    }

    private static string StringArray(EquatableArray<string> values) {
        if (values.Count == 0) return "global::System.Array.Empty<string>()";

        return "new string[] { " + string.Join(", ", values.Select(static value => SourceLiterals.String(value))) + " }";
    }

    private static string DoubleLiteral(double value) {
        return value > 0 ? value.ToString("R", CultureInfo.InvariantCulture) + "d" : "0d";
    }

    private static string Identifier(string name) {
        return SyntaxFacts.GetKeywordKind(name) != SyntaxKind.None ? "@" + name : name;
    }

    private static string EscapeXml(string text) {
        return text.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\r", " ").Replace("\n", " ");
    }
}
